ACTIVE_PATHWAY_IDS = {
    "asthma",
    "fever-sepsis-infant",
    "migraine",
    "pneumonia",
    "ssti",
}


def _pdf_basename_from_url(pdf_url: str) -> str:
    return unquote(Path(urlparse(pdf_url).path).name)


def _build_document_reference_by_doc_name() -> Dict[str, Dict[str, str]]:
    reference_by_doc_name: Dict[str, Dict[str, str]] = {}

    for pathway in PATHWAY_CATALOG:
        for resource in pathway["resources"]:
            doc_name = resource.get("doc_name")
            pdf_url = resource.get("pdf_url")
            if not doc_name or not pdf_url:
                continue
            reference = {
                "pathway_id": pathway["id"],
                "resource_id": resource["id"],
                "doc_name": doc_name,
                "pdf_url": pdf_url,
                "pdf_basename": _pdf_basename_from_url(pdf_url),
            }
            reference_by_doc_name[doc_name] = reference
            medembed_id = resource.get("medembed_id")
            if medembed_id:
                reference_by_doc_name[medembed_id] = reference

    return reference_by_doc_name


def _build_source_reference_by_key() -> Dict[str, Dict[str, str]]:
    reference_by_key: Dict[str, Dict[str, str]] = {}
    resource_id_counts: Dict[str, int] = {}

    for pathway in PATHWAY_CATALOG:
        reference_by_key[pathway["id"]] = {
            "pathway_id": pathway["id"],
            "preview_resource_id": pathway["default_resource_id"],
        }
        for resource in pathway["resources"]:
            resource_id_counts[resource["id"]] = resource_id_counts.get(resource["id"], 0) + 1

    for pathway in PATHWAY_CATALOG:
        for resource in pathway["resources"]:
            reference = {
                "pathway_id": pathway["id"],
                "preview_resource_id": resource["id"],
            }
            if resource_id_counts.get(resource["id"], 0) == 1:
                reference_by_key[resource["id"]] = reference
            medembed_id = resource.get("medembed_id")
            if medembed_id:
                reference_by_key[medembed_id] = reference

    for alias in HIDDEN_SOURCE_ALIASES:
        reference_by_key[alias["source_file"]] = {
            "pathway_id": alias["pathway_id"],
            "preview_resource_id": alias["preview_resource_id"],
        }

    return reference_by_key


PATHWAY_BY_ID: Dict[str, Dict[str, str]] = {
    pathway["id"]: pathway for pathway in PATHWAY_CATALOG
}


DOCUMENT_REFERENCE_BY_DOC_NAME = _build_document_reference_by_doc_name()


SOURCE_REFERENCE_BY_KEY = _build_source_reference_by_key()


def list_pathways() -> List[Dict[str, str]]:
    if ACTIVE_PATHWAY_IDS is None:
        return PATHWAY_CATALOG
    return [pathway for pathway in PATHWAY_CATALOG if pathway["id"] in ACTIVE_PATHWAY_IDS]


def get_pathway_by_id(pathway_id: str) -> Optional[Dict[str, str]]:
    return PATHWAY_BY_ID.get(pathway_id)


def get_pathway_resource(pathway_id: str, resource_id: Optional[str] = None) -> Optional[Dict[str, str]]:
    pathway = get_pathway_by_id(pathway_id)
    if not pathway:
        return None

    desired_resource_id = resource_id or pathway["default_resource_id"]
    for resource in pathway["resources"]:
        if resource["id"] == desired_resource_id:
            return resource
    return None


def get_pathway_retrieval_documents(pathway_id: str) -> List[str]:
    pathway = get_pathway_by_id(pathway_id)
    if not pathway:
        return []
    return list(pathway.get("retrieval_document_ids", []))


def resolve_document_reference(doc_name: Optional[str]) -> Optional[Dict[str, str]]:
    if not doc_name:
        return None
    reference = DOCUMENT_REFERENCE_BY_DOC_NAME.get(doc_name)
    return dict(reference) if reference else None


def resolve_source_reference(source_key: Optional[str]) -> Optional[Dict[str, str]]:
    if not source_key:
        return None
    reference = SOURCE_REFERENCE_BY_KEY.get(source_key)
    return dict(reference) if reference else None
